import { formatISO } from 'date-fns';

const todos = [];

/* Add a todo */
export function add(args) {
  const { task, dueDate = undefined } = args;
  if (!task) throw new Error('Must provide a task to add. Usage: --cmd=add task=...');
  dueDate &&= /^\d{4}-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01])$/.test(dueDate)
    ? formatISO(new Date(dueDate), { representation: 'date' })
    : dueDate;
  todos.push({ task, dueDate });
  return JSON.stringify(todos);
}

/* List all todos */
export function list(args) {
  if (todos.length === 0) return 'No Tasks';
  const tasks = [];
  for (const todo of todos) {
    let taskString = todo.task;
    !todo.dueDate && (taskString += ` ${new Date().toISOString()}`);
    if (todo.dueDate) taskString += ` ${todo.dueDate}`;
    tasks.push(taskString);
  }
  return tasks.join('\n');
}

function count(args) {
  return JSON.stringify({ count: todos.length });
}
